'use strict';
const aiDraft={career:'All careers',category:'All templates',query:'',text:'',selected:[],result:null,chosen:null,busy:false,error:'',controller:null,requestId:0,applied:false,pending:null};
const aiExample=`My name is Jordan Lee. My email is jordan.lee@example.com. I live in Bengaluru, India. My portfolio is jordanlee.example.com.
I'm a frontend developer. I worked at Example Studio from July 2023 to September 2026, building an accessible component library used across four products and reducing page load time by 32%.
Before that, I was a web development intern at Campus Lab from January to June 2023. I built a student events website with React.
I completed a B.Tech in Computer Science at Example University from 2019 to 2023.
Skills: JavaScript, TypeScript, React, HTML, CSS, accessibility, Git, and Figma.
My personal project is Study Circle, a study-group scheduling app. I built its responsive frontend and tested it with 20 students.
Languages: English and Hindi.`;
function renderAi(){if(aiDraft.result){if(aiDraft.applied)aiDraft.result=state.data;renderAiPreviews();return}renderAiInput()}
function renderAiInput(){
 $('#ai-view').innerHTML=`<div class="ai-shell"><div class="ai-intro"><div class="eyebrow">A LITTLE AI. A LOT OF YOU.</div><h1 id="ai-title">Your details.<br>Your next <span>chapter.</span></h1><p>Paste your experience once. See it in the styles you love.</p><div class="ai-journey"><span class="current">01 &nbsp; Add details</span><span>02 &nbsp; Choose styles</span><span>03 &nbsp; Preview & export</span></div></div>
 <div class="ai-input-layout"><section class="ai-paste-panel" aria-labelledby="ai-paste-title"><div class="ai-section-heading"><span class="ai-step-number">01</span><div><h2 id="ai-paste-title">Start with your story.</h2><p>Notes, an old resume, or a little of everything.</p></div></div><label for="ai-details">Paste your details</label><textarea id="ai-details" maxlength="16000" rows="12" placeholder="Name and contact details\nWork experience and achievements\nEducation, skills, and projects\nCertifications, languages, or awards" ${aiDraft.busy?'readonly':''}>${esc(aiDraft.text)}</textarea><div class="ai-text-meta"><button class="text-button" id="ai-use-example" ${aiDraft.busy?'disabled':''}>Try an example</button><span id="ai-char-count">${aiDraft.text.length.toLocaleString()} / 16,000</span></div><div class="ai-privacy"><span aria-hidden="true">✳</span><p>Your text is sent to an <strong>AI service</strong> to organize it. Include only details you want on your resume. Review the result before exporting.</p></div><p class="ai-draft-note">Your current draft stays unchanged until you use a preview.</p></section>
 <section class="ai-styles-panel" aria-labelledby="ai-styles-title"><div class="ai-section-heading"><span class="ai-step-number">02</span><div><h2 id="ai-styles-title">Pick 1–4 favorites.</h2><p>The same details. A different first impression.</p></div></div><div class="ai-style-filters"><label for="ai-template-search" class="sr-only">Search AI templates</label><input type="search" id="ai-template-search" placeholder="Search ${templates.length} styles" value="${esc(aiDraft.query)}"><label for="ai-template-category" class="sr-only">AI template category</label><select id="ai-template-category">${['All templates','Fresh styles','With photo',...templateCategories].map(c=>`<option ${c===aiDraft.category?'selected':''}>${c}</option>`).join('')}</select><label for="ai-template-career" class="sr-only">AI template career</label><select id="ai-template-career">${['All careers',...careerCategories].map(c=>`<option ${c===aiDraft.career?'selected':''}>${c}</option>`).join('')}</select></div><div id="ai-selected-list" class="ai-selected-list" aria-label="Selected styles"></div><p id="ai-style-count" class="ai-style-count" aria-live="polite"></p><div class="ai-style-grid" id="ai-style-grid" role="region" aria-label="Choose resume styles" tabindex="0"></div></section></div>
 <div class="ai-build-bar"><div class="ai-build-main"><div><strong id="ai-selection-count">${aiDraft.selected.length} of 4 styles selected</strong><p id="ai-selection-hint">Choose at least 1 style and add your details.</p></div><button class="button dark" id="ai-build-button" ${aiDraft.busy?'disabled':''}>${aiDraft.busy?'<span class="ai-spinner" aria-hidden="true"></span> Creating your '+(aiDraft.selected.length===1?'preview':'previews')+'…':aiDraft.selected.length===1?'Create my preview':'Create my previews'}</button><button class="text-button ${aiDraft.busy?'':'hidden'}" id="ai-cancel">Cancel</button></div><div id="ai-progress" class="ai-progress ${aiDraft.busy?'':'hidden'}" role="status">Organizing your details with AI. This may take a moment.</div><div id="ai-error" class="ai-error ${aiDraft.error?'':'hidden'}" role="alert" tabindex="-1">${esc(aiDraft.error)}</div></div><p class="ai-bottom-note">One selected template. <strong>₹0 · Free export.</strong> <button class="text-button" data-view="editor">Prefer to enter details yourself?</button></p></div>`;
 renderAiStyles();updateAiInputControls();
}
function renderAiStyles(){
 const list=matchingTemplates(aiDraft.category,aiDraft.query,'all',aiDraft.career);
 $('#ai-style-count').textContent=`${list.length} of ${templates.length} styles · Scroll to explore`;
 $('#ai-style-grid').innerHTML=list.length?list.map(t=>`<button class="ai-style-card ${aiDraft.selected.includes(t.id)?'picked':''}" data-ai-pick="${t.id}" aria-label="Select ${t.name}" aria-pressed="${aiDraft.selected.includes(t.id)}" ${aiDraft.busy?'disabled':''}><div class="ai-style-cover" style="--card-bg:${t.bg}">${mini(t)}<span class="ai-pick-mark" aria-hidden="true">${aiDraft.selected.includes(t.id)?'✓':'+'}</span></div><span class="ai-style-name">${t.name}</span><span class="ai-style-category">${t.category}</span></button>`).join(''):'<div class="gallery-empty"><h3>No matching styles.</h3><p>Try another search or category.</p></div>';
 renderAiSelections();
}
function renderAiSelections(){if(!$('#ai-selected-list'))return;$('#ai-selected-list').innerHTML=aiDraft.selected.length?aiDraft.selected.map(id=>`<button data-ai-remove="${id}" aria-label="Deselect ${templates.find(t=>t.id===id).name}" ${aiDraft.busy?'disabled':''}>${templates.find(t=>t.id===id).name} &nbsp; ×</button>`).join(''):'<p>Your favorites will appear here.</p>'}
document.addEventListener('input',e=>{if(e.target.id==='ai-template-search'){aiDraft.query=e.target.value;renderAiStyles()}});
document.addEventListener('change',e=>{if(e.target.id==='ai-template-category'){aiDraft.category=e.target.value;renderAiStyles()}if(e.target.id==='ai-template-career'){aiDraft.career=e.target.value;renderAiStyles()}});
document.addEventListener('click',e=>{const button=e.target.closest('[data-ai-remove]');if(button)pickAiStyle(button.dataset.aiRemove)});
function updateAiInputControls(){
 renderAiSelections();
 const count=aiDraft.selected.length,ready=count>=1&&count<=4&&aiDraft.text.trim().length>=40;
 if(!$('#ai-build-button'))return;
 $('#ai-build-button').disabled=aiDraft.busy||!ready;
 $('#ai-build-button').innerHTML=aiDraft.busy?'<span class="ai-spinner" aria-hidden="true"></span> Creating your '+(count===1?'preview':'previews')+'…':count===1?'Create my preview':'Create my previews';
 $('#ai-build-button').setAttribute('aria-busy',String(aiDraft.busy));
 $('#ai-cancel').classList.toggle('hidden',!aiDraft.busy);
 $('#ai-progress').classList.toggle('hidden',!aiDraft.busy);
 $('#ai-error').classList.toggle('hidden',!aiDraft.error);
 $('#ai-error').textContent=aiDraft.error;
 $('#ai-details').readOnly=aiDraft.busy;
 $('#ai-use-example').disabled=aiDraft.busy;
 $('#ai-selection-count').textContent=`${count} of 4 styles selected`;
 $('#ai-selection-hint').textContent=count<1?'Choose at least 1 style to preview.':aiDraft.text.trim().length<40?'Add at least 40 characters of resume details.':'Ready when you are. Your PDF export is free.';
 $('#ai-char-count').textContent=`${aiDraft.text.length.toLocaleString()} / 16,000`;
 $$('[data-ai-pick]').forEach(button=>{const selected=aiDraft.selected.includes(button.dataset.aiPick);button.classList.toggle('picked',selected);button.setAttribute('aria-pressed',String(selected));button.disabled=aiDraft.busy;button.querySelector('.ai-pick-mark').textContent=selected?'✓':'+'});
}
function pickAiStyle(id){if(aiDraft.busy)return;const index=aiDraft.selected.indexOf(id);if(index>=0)aiDraft.selected.splice(index,1);else if(aiDraft.selected.length<4)aiDraft.selected.push(id);else{notify('You can compare up to 4 templates. Deselect one to choose another.');return}updateAiInputControls()}
function normalizeAiResume(input){
 if(!input||typeof input!=='object'||Array.isArray(input))throw new Error('The AI response was incomplete. Please try again.');
 const result=empty();for(const key of ['name','role','email','phone','location','website','summary','skills','extraTitle','extra']){if(typeof input[key]!=='string'||input[key].length>20000)throw new Error('The AI response was incomplete. Please try again.');result[key]=input[key]}
 for(const [key,fields] of Object.entries({experience:['title','company','dates','details'],education:['degree','school','dates','details'],projects:['title','link','details']})){if(!Array.isArray(input[key])||input[key].length>40)throw new Error('The AI response was incomplete. Please try again.');result[key]=input[key].map(entry=>{if(!entry||typeof entry!=='object')throw new Error('The AI response was incomplete. Please try again.');return Object.fromEntries(fields.map(field=>{if(typeof entry[field]!=='string')throw new Error('The AI response was incomplete. Please try again.');return [field,entry[field]]}))})}
 return result;
}
async function buildAiPreviews(){
 if(aiDraft.busy||aiDraft.selected.length<1||aiDraft.selected.length>4||aiDraft.text.trim().length<40||aiDraft.text.length>16000)return;
 aiDraft.busy=true;aiDraft.error='';aiDraft.controller=new AbortController();const requestId=++aiDraft.requestId;updateAiInputControls();
 const timer=setTimeout(()=>aiDraft.controller?.abort('timeout'),60000);
 try{const response=await fetch('/api/extract',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({text:aiDraft.text}),signal:aiDraft.controller.signal});let body;try{body=await response.json()}catch(e){throw new Error('AI extraction is unavailable. Your text is still here; try again shortly.')}if(!response.ok)throw new Error(typeof body.error==='string'?body.error:'Could not extract your details. Please try again.');const result=normalizeAiResume(body.data);if(requestId!==aiDraft.requestId)return;aiDraft.result=result;aiDraft.chosen=aiDraft.selected[0];aiDraft.applied=false;aiDraft.busy=false;if(currentView==='ai'){renderAiPreviews();window.scrollTo({top:0,behavior:'smooth'})}else notify('Your AI previews are ready in AI builder.')}
 catch(error){if(requestId!==aiDraft.requestId)return;aiDraft.error=error.name==='AbortError'||error.name==='TimeoutError'||error==='timeout'?'The request took too long. Your text is still here; please try again.':error.message||'AI extraction failed. Please try again.';aiDraft.busy=false;if(currentView==='ai'){updateAiInputControls();$('#ai-error')?.focus({preventScroll:true})}else notify('AI extraction could not finish. Your text is still in AI builder.')}
 finally{clearTimeout(timer);if(requestId===aiDraft.requestId){aiDraft.controller=null;aiDraft.busy=false}}
}
function cancelAiRequest(){aiDraft.requestId++;aiDraft.controller?.abort();aiDraft.controller=null;aiDraft.busy=false;aiDraft.error='';updateAiInputControls();notify('Canceled. Your details are still here.')}
function renderAiPreviews(){
 const data=aiDraft.result;
 $('#ai-view').innerHTML=`<div class="ai-shell ai-results"><div class="ai-results-heading"><div><div class="eyebrow">YOUR DETAILS. YOUR CHOICES.</div><h1 id="ai-title">Your story.<br>${aiDraft.selected.length===1?'Ready to shine.':'A few ways to shine.'}</h1><p>${aiDraft.selected.length===1?'Review your preview, then export it for free.':`Compare your ${aiDraft.selected.length} previews, then choose one to export.`}</p></div><button class="button outline" id="ai-start-over">Change details or styles</button></div>
 <div class="ai-review-banner"><span class="ai-review-symbol" aria-hidden="true">✳</span><div><strong>${esc(data.name||'Your extracted details')}</strong><p>${data.experience.length} experience ${data.experience.length===1?'entry':'entries'} · ${data.education.length} education ${data.education.length===1?'entry':'entries'} · ${data.projects.length} ${data.projects.length===1?'project':'projects'}</p><p>AI can make mistakes. Check names, dates, contact details, and achievements.</p></div><button class="button outline" id="ai-edit-result">Review & edit details</button></div>
 <div class="ai-comparison-grid">${aiDraft.selected.map(id=>{const t=templates.find(t=>t.id===id);return `<article class="ai-preview-card ${aiDraft.chosen===id?'chosen':''}" data-ai-card="${id}"><div class="ai-preview-card-header"><div><h2>${t.name}</h2><p>${t.category}</p></div><button class="ai-choose" data-ai-choose="${id}" aria-pressed="${aiDraft.chosen===id}" aria-label="Choose ${t.name} for export">${aiDraft.chosen===id?'✓ Selected':'Select'}</button></div><div class="ai-paper-window" role="region" aria-label="${t.name} resume preview" tabindex="0">${resumeMarkup(data,id,t.color,state.photo,state.photoPosition)}</div><div class="ai-preview-card-footer"><span>Full resume preview · Scroll to review</span><span>₹0 export</span></div></article>`}).join('')}</div>
 <div class="ai-export-bar"><div><span class="ai-export-kicker">YOUR SELECTED TEMPLATE</span><strong id="ai-chosen-name"></strong><p>1 template · PDF</p></div><div class="ai-price"><strong>₹0</strong><span>Free export</span></div><button class="button dark" id="ai-export-selected">Export selected · Free</button></div><p class="ai-bottom-note">No card needed. Review the PDF’s page breaks before sending.</p></div>`;
 updateAiChosen();
}
function updateAiChosen(){const t=templates.find(t=>t.id===aiDraft.chosen);if($('#ai-chosen-name'))$('#ai-chosen-name').textContent=t.name;$$('[data-ai-choose]').forEach(button=>{const chosen=button.dataset.aiChoose===aiDraft.chosen;button.setAttribute('aria-pressed',String(chosen));button.textContent=chosen?'✓ Selected':'Select'});$$('[data-ai-card]').forEach(card=>card.classList.toggle('chosen',card.dataset.aiCard===aiDraft.chosen))}
function useAiResult(action){if(!aiDraft.result||!aiDraft.selected.includes(aiDraft.chosen))return;aiDraft.pending=action;if(hasContent()&&!aiDraft.applied&&JSON.stringify(state.data)!==JSON.stringify(aiDraft.result)){$('#ai-replace-dialog').showModal();return}commitAiResult()}
function commitAiResult(){const t=templates.find(t=>t.id===aiDraft.chosen);state.data=structuredClone(aiDraft.result);state.template=t.id;state.color=t.color;state.step=0;aiDraft.applied=true;save();const action=aiDraft.pending;aiDraft.pending=null;if($('#ai-replace-dialog').open)$('#ai-replace-dialog').close();if(action==='edit'){showView('editor');goStep(0)}else{requestExport();}}
document.addEventListener('input',event=>{if(event.target.id==='ai-details'){aiDraft.text=event.target.value;updateAiInputControls()}});
document.addEventListener('click',event=>{const button=event.target.closest('button');if(!button)return;if(button.dataset.aiPick)pickAiStyle(button.dataset.aiPick);if(button.dataset.aiChoose){aiDraft.chosen=button.dataset.aiChoose;updateAiChosen()}switch(button.id){case 'ai-use-example':aiDraft.text=aiExample;$('#ai-details').value=aiExample;updateAiInputControls();break;case 'ai-build-button':buildAiPreviews();break;case 'ai-cancel':cancelAiRequest();break;case 'ai-start-over':aiDraft.result=null;aiDraft.applied=false;aiDraft.error='';renderAiInput();window.scrollTo({top:0,behavior:'smooth'});break;case 'ai-edit-result':useAiResult('edit');break;case 'ai-export-selected':useAiResult('export');break;case 'ai-confirm-replace':commitAiResult();break}});
if(location.hash==='#ai')showView('ai');
